const $=s=>document.querySelector(s), KEY='playlog.v1';
const demo=[
{id:'d1',title:'ゼルダの伝説 ブレス オブ ザ ワイルド',display:'THE LEGEND OF<br>ZELDA',subtitle:'BREATH OF THE WILD',platform:'Nintendo Switch',status:'プレイ中',hours:86,rating:5,favorite:true,color:'linear-gradient(155deg,#87a99b,#355e58 55%,#233c37)',notes:'サンプルの記録です。自由に編集・削除できます。'},
{id:'d2',title:'ELDEN RING',display:'ELDEN<br>RING',subtitle:'THE LANDS BETWEEN',platform:'PC / Steam',status:'クリア済み',hours:124,rating:5,favorite:true,steam:1245620,color:'#5c5940',notes:''},
{id:'d3',title:'ペルソナ５ ザ・ロイヤル',display:'PERSONA 5<br>ROYAL',subtitle:'TAKE YOUR HEART',platform:'PlayStation 5',status:'クリア済み',hours:112,rating:5,favorite:false,steam:1687950,color:'#8c2935',notes:''},
{id:'d4',title:'Stardew Valley',display:'Stardew<br>Valley',subtitle:'A LITTLE FARM. A NEW LIFE.',platform:'PC / Steam',status:'プレイ中',hours:67,rating:4,favorite:false,steam:413150,color:'#497b83',notes:''},
{id:'d5',title:'Hollow Knight',display:'HOLLOW<br>KNIGHT',subtitle:'DESCEND INTO THE DARK',platform:'Nintendo Switch',status:'クリア済み',hours:38,rating:5,favorite:true,steam:367520,color:'#273a59',notes:''},
{id:'d6',title:'あつまれ どうぶつの森',display:'あつまれ<br>どうぶつの森',subtitle:'YOUR OWN LITTLE ISLAND',platform:'Nintendo Switch',status:'おやすみ中',hours:210,rating:4,favorite:false,color:'linear-gradient(145deg,#a5cba7,#6aa897 50%,#4f8a82)',notes:''},
{id:'d7',title:'NieR:Automata',display:'NieR:<br>Automata',subtitle:'GLORY TO MANKIND',platform:'PlayStation 4',status:'クリア済み',hours:46,rating:5,favorite:false,steam:524220,color:'#8e8e7e',notes:''},
{id:'d8',title:'HADES',display:'HADES',subtitle:'THERE IS NO ESCAPE',platform:'PC / Steam',status:'これから',hours:0,rating:0,favorite:false,steam:1145360,color:'#7d3937',notes:''}];
let games=[],isDemo=true,filter='all';try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data.games))throw Error();games=data.games;isDemo=!!data.isDemo}else games=structuredClone(demo)}catch{games=structuredClone(demo);setTimeout(()=>toast('保存データを読み込めませんでした。サンプルを表示します。'),400)}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function persist(next,demoState=isDemo){try{localStorage.setItem(KEY,JSON.stringify({games:next,isDemo:demoState}));games=next;isDemo=demoState;render();return true}catch{toast('保存できませんでした。ブラウザの保存容量をご確認ください。');return false}}
function render(){const q=$('#search').value.toLocaleLowerCase();let list=games.filter(g=>(filter==='all'||filter==='favorite'&&g.favorite||g.status===filter)&&`${g.title} ${g.platform} ${g.notes}`.toLocaleLowerCase().includes(q));const sort=$('#sort').value;if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title,'ja'));if(sort==='hours')list.sort((a,b)=>b.hours-a.hours);$('#total').innerHTML=games.length+'<small>本</small>';$('#playing').innerHTML=games.filter(g=>g.status==='プレイ中').length+'<small>本</small>';$('#completed').innerHTML=games.filter(g=>g.status==='クリア済み').length+'<small>本</small>';$('#hours').innerHTML=games.reduce((n,g)=>n+Number(g.hours||0),0).toLocaleString()+'<small>時間</small>';$('#nav-count').textContent=games.length;$('#list-count').textContent=`${list.length} GAMES`;$('#sample-note').hidden=!isDemo;$('#clear-demo').hidden=!isDemo;$('#grid').innerHTML=list.map(g=>`<article class="card"><div class="cover" style="--cover:${esc(g.color||'linear-gradient(140deg,#5a8c75,#294b51)')}"><button class="badge" data-edit="${esc(g.id)}">${esc(g.status)}</button>${g.steam?`<img src="https://cdn.akamai.steamstatic.com/steam/apps/${Number(g.steam)}/library_600x900.jpg" alt="" loading="lazy" onerror="this.remove()">`:''}<div class="cover-title" ${g.steam?'style="opacity:0"':''}>${g.display||esc(g.title)}<small>${esc(g.subtitle||'MY GAME COLLECTION')}</small></div><button class="heart ${g.favorite?'on':''}" data-heart="${esc(g.id)}" aria-label="${esc(g.title)}のお気に入りを切り替え" aria-pressed="${!!g.favorite}">${g.favorite?'♥':'♡'}</button></div><div class="card-info"><button class="game-title" data-edit="${esc(g.id)}" title="${esc(g.title)}">${esc(g.title)}</button><div class="platform">${esc(g.platform)}</div><div class="card-bottom"><span class="${g.rating?'stars':'unrated'}" aria-label="${g.rating?g.rating+'点':'未評価'}">${g.rating?'★'.repeat(g.rating)+'☆'.repeat(5-g.rating):'未評価'}</span><span class="duration">◷ ${Number(g.hours).toLocaleString()} h</span></div></div></article>`).join('');$('#empty').hidden=!!list.length;if(!list.length){$('#empty h3').textContent=games.length?'ゲームが見つかりません':'次の冒険を記録しよう';$('#empty p').textContent=games.length?'検索条件やプレイ状況を変えてみてください。':'ゲームを追加すると、ここにコレクションが並びます。'}document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.classList.contains('nav')&&b.dataset.filter===filter);b.classList.toggle('selected',!b.classList.contains('nav')&&b.dataset.filter===filter)})}
function openEditor(id){const g=games.find(x=>x.id===id);$('#form').reset();$('#game-id').value=g?.id||'';$('#dialog-title').textContent=g?'ゲームを編集':'ゲームを追加';$('#title').value=g?.title||'';$('#platform').value=g?.platform||'Nintendo Switch';$('#status').value=g?.status||'プレイ中';$('#time').value=g?.hours||0;$('#rating').value=g?.rating||0;$('#notes').value=g?.notes||'';$('#favorite').checked=g?.favorite||false;$('#delete').hidden=!g;$('#error').textContent='';$('#editor').showModal()}
document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render()}const ed=e.target.closest('[data-edit]');if(ed)openEditor(ed.dataset.edit);const h=e.target.closest('[data-heart]');if(h)persist(games.map(g=>g.id===h.dataset.heart?{...g,favorite:!g.favorite}:g));});
$('#search').addEventListener('input',render);$('#sort').addEventListener('change',render);$('#add').onclick=()=>openEditor();$('#empty-add').onclick=()=>openEditor();$('#close').onclick=()=>$('#editor').close();$('#editor').addEventListener('click',e=>{if(e.target===$('#editor')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#form').addEventListener('submit',e=>{e.preventDefault();const title=$('#title').value.trim();if(!title){$('#error').textContent='タイトルを入力してください。';return}const id=$('#game-id').value;const old=games.find(g=>g.id===id);const g={...old,id:id||crypto.randomUUID(),title,display:undefined,subtitle:undefined,platform:$('#platform').value,status:$('#status').value,hours:Number($('#time').value),rating:Number($('#rating').value),notes:$('#notes').value.trim(),favorite:$('#favorite').checked};const next=id?games.map(x=>x.id===id?g:x):[g,...games];if(persist(next,isDemo&&!!id)){filter='all';$('#search').value='';render();$('#editor').close();toast('ゲームを保存しました')}});
$('#delete').onclick=()=>{if(confirm('このゲームの記録を削除しますか？')){if(persist(games.filter(g=>g.id!==$('#game-id').value))){$('#editor').close();toast('記録を削除しました')}}};
$('#clear-demo').onclick=()=>{if(confirm('サンプルのゲームを削除して、空のライブラリから始めますか？追加したゲームは残ります。')){if(persist(games.filter(g=>!/^d\d+$/.test(g.id)),false))toast('自分だけのライブラリをはじめましょう')}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),games},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='playlog.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('記録を書き出しました')};render();
